.ring-container { position: relative; width: 150px; height: 150px; }
.ring-bg { fill: none; stroke: #333; stroke-width: 12; }
.ring-progress {
  fill: none; stroke: #00ffcc; stroke-width: 12;
  stroke-linecap: round; stroke-dasharray: 408; stroke-dashoffset: 408;
  animation: fillRing 2s forwards cubic-bezier(0.175, 0.885, 0.32, 1.275);
  filter: drop-shadow(0 0 10px #00ffcc); transform: rotate(-90deg); transform-origin: 50% 50%;
}
@keyframes fillRing { to { stroke-dashoffset: 100; } }
